# Prime Number Checker
import math
num = [[int]]([[input]]("Enter a positive integer: "))
[[if]] num < 2:
    [[print]]("Not Prime")
else:
    is_prime = True
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            is_prime = False
            break
    if is_prime:
        print(f"{num} is Prime")
    else:
        print(f"{num} is Not Prime")

# Temperature Converter (All Scales)
[[print]]("Convert from: C, F, K")
from_scale = [[input]]("From scale: ").upper()
temp = [[float]](input("Enter temperature: "))
print("Convert to: C, F, K")
to_scale = input("To scale: ").upper()
# Convert to Celsius first
[[if]] from_scale == 'C':
    c = temp
elif from_scale == 'F':
    c = (temp - 32) * 5/9
elif from_scale == 'K':
    c = temp - 273.15
else:
    print("Invalid from scale")
    c = None
if c is not None:
    if to_scale == 'C':
        result = c
    elif to_scale == 'F':
        result = c * 9/5 + 32
    elif to_scale == 'K':
        result = c + 273.15
    else:
        print("Invalid to scale")
        result = None
    if result is not None:
        print(f"Result: {result} {to_scale}")
